parameters.text:
=Triage this new Matrix42 service desk ticket.

Ticket number: {{ $("Combine ticket and categories").item.json.TicketNumber }}
Subject: {{ $("Combine ticket and categories").item.json.Subject }}
Description:
{{ $("Combine ticket and categories").item.json.Description || "(no description)" }}

Available categories (ID | name):
{{ $("Combine ticket and categories").item.json.categories.map(category => category.ID + " | " + category.Name).join("\n") }}

Write summary, suggestedSolution, majorIncidentReason and reasoning in {{ $("Combine ticket and categories").item.json.noteLanguage }}.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "ticketType": {
      "type": "string",
      "enum": [
        "incident",
        "serviceRequest"
      ],
      "description": "incident = something is broken or degraded; serviceRequest = a request for something new, access or information"
    },
    "categoryId": {
      "type": "string",
      "description": "ID of the best matching category, copied exactly from the list"
    },
    "categoryName": {
      "type": "string"
    },
    "impact": {
      "type": "integer",
      "minimum": 1,
      "maximum": 3,
      "description": "1 = one person, 2 = a team or department, 3 = the whole company"
    },
    "urgency": {
      "type": "integer",
      "minimum": 1,
      "maximum": 3,
      "description": "1 = partial outage, 2 = malfunction, 3 = total outage"
    },
    "summary": {
      "type": "string",
      "description": "One sentence that a dispatcher can read at a glance"
    },
    "suggestedSolution": {
      "type": "string",
      "description": "First troubleshooting steps or fulfilment hints for the agent"
    },
    "majorIncidentSuspected": {
      "type": "boolean"
    },
    "majorIncidentReason": {
      "type": "string",
      "description": "Why this might be a major incident; empty when not suspected"
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "reasoning": {
      "type": "string",
      "description": "Short explanation of the classification"
    }
  },
  "required": [
    "ticketType",
    "categoryId",
    "categoryName",
    "impact",
    "urgency",
    "summary",
    "suggestedSolution",
    "majorIncidentSuspected",
    "majorIncidentReason",
    "confidence",
    "reasoning"
  ]
}

parameters.comments:
={{ (() => {
  // Internal note for the service desk with everything the AI concluded
  const result = $("Analyze ticket with Claude").item.json.output;
  const threshold = $("Combine ticket and categories").item.json.confidenceThreshold;
  const applied = result.confidence >= threshold;
  return [
    "AI triage",
    "Summary: " + result.summary,
    "Suggested solution: " + result.suggestedSolution,
    "Classification: " + (result.ticketType === "incident" ? "Incident" : "Service request") + ", category " + result.categoryName + ", impact " + result.impact + ", urgency " + result.urgency,
    "Confidence: " + Math.round(result.confidence * 100) + "% (" + (applied ? "applied automatically" : "below " + Math.round(threshold * 100) + "%, not applied, please classify manually") + ")",
    result.majorIncidentSuspected ? "Possible major incident: " + result.majorIncidentReason : "",
    "Reasoning: " + result.reasoning
  ].filter(Boolean).join("\n");
})() }}
